class Solution {
public:
    long long minimumTime(vector<int>& power) {
        int n = power.size(), states = 1 << n;
        vector<long long> dp(states, LLONG_MAX / 4);
        dp[0] = 0;
        for (int mask = 0; mask < states; ++mask) {
            int gain = __builtin_popcount((unsigned)mask) + 1;
            for (int i = 0; i < n; ++i) if (!(mask & (1 << i))) {
                long long days = (power[i] + (long long)gain - 1) / gain;
                dp[mask | (1 << i)] = min(dp[mask | (1 << i)], dp[mask] + days);
            }
        }
        return dp.back();
    }
};
